// n8n Code node (JavaScript)

// Número original vindo do Edit Fields
let numeroOriginal = $('Edit Fields1').first().json.Telefone || "";

// Limpa tudo que não for dígito
let numeroLimpo = numeroOriginal.replace(/\D/g, "");

// Se tiver 10 ou 11 dígitos, adiciona 55 na frente
if (numeroLimpo.length === 10 || numeroLimpo.length === 11) {
  numeroLimpo = "55" + numeroLimpo;
}

// Monta o número corrigido
const telefoneCorrigido = numeroLimpo;

// Pega os últimos 8 dígitos
const telefoneUltimos8 = telefoneCorrigido.slice(-8);

return [
  {
    json: {
      TelefoneCorrigido: telefoneCorrigido,
      TelefoneUltimos8: telefoneUltimos8
    }
  }
];

// n8n Code node (JavaScript)

// ---- helpers ----
function safeParse(v) {
  if (v == null) return null;
  if (typeof v === 'object') return v;
  try { return JSON.parse(String(v)); } catch { return null; }
}

function getFirstByField(cf = [], wanted = []) {
  if (!Array.isArray(cf)) return null;
  const f = cf.find(x =>
    wanted.includes(x.field_code) ||
    wanted.includes(x.field_name)
  );
  return f?.values?.[0]?.value ?? null;
}

function getFirstPhone(cf = []) {
  return getFirstByField(cf, ['PHONE', 'Phone']);
}

function getFirstEmail(cf = []) {
  return getFirstByField(cf, ['EMAIL', 'Email', 'E-mail']);
}

function scoreContact(c) {
  if (!c || typeof c !== 'object') return -1;
  let s = 0;
  if (c.name) s += 2;
  if (getFirstPhone(c.custom_fields_values)) s += 2;
  s += Array.isArray(c.custom_fields_values) ? c.custom_fields_values.length : 0;
  s += Array.isArray(c._embedded?.tags) ? c._embedded.tags.length : 0;
  s += Array.isArray(c._embedded?.companies) ? c._embedded.companies.length : 0;
  if (c.first_name) s += 1;
  if (c.last_name) s += 1;
  if (c.responsible_user_id) s += 1;
  return s;
}

// ---- main ----
const out = [];

for (const item of $input.all()) {
  const data = safeParse(item.json?.data) || safeParse(item.json) || item.json;
  if (!data || typeof data !== 'object') continue;

  const contacts = data._embedded?.contacts ?? [];
  const leadRows = [];

  for (const contact of contacts) {
    const leads = contact._embedded?.leads ?? [];
    for (const ld of leads) {
      leadRows.push({
        json: {
          contact_id: contact.id ?? null,
          contact_name: contact.name ?? null,
          phone: getFirstPhone(contact.custom_fields_values) ?? null,
          email: getFirstEmail(contact.custom_fields_values) ?? null, // sempre presente
          contact_link: contact._links?.self?.href ?? null,
          lead_id: ld?.id ?? null,
          lead_link: ld?._links?.self?.href ?? null,
        }
      });
    }
  }

  if (leadRows.length > 0) {
    out.push(...leadRows);
  } else {
    if (contacts.length > 0) {
      let best = contacts[0];
      let bestScore = scoreContact(best);
      for (let i = 1; i < contacts.length; i++) {
        const sc = scoreContact(contacts[i]);
        if (sc > bestScore) {
          best = contacts[i];
          bestScore = sc;
        }
      }
      out.push({
        json: {
          contact_id: best.id ?? null,
          contact_name: best.name ?? null,
          phone: getFirstPhone(best.custom_fields_values) ?? null,
          email: getFirstEmail(best.custom_fields_values) ?? null, // sempre presente
          contact_link: best._links?.self?.href ?? null,
          lead_id: null,
          lead_link: null,
          _note: "Sem leads; retornado contato mais completo"
        }
      });
    }
  }
}

return out;

// n8n Code node (JavaScript) — retorna 1 lead aberto e não perdido
// Mantém todos os campos anteriores + tags_string (com vírgula no final quando não-vazio)
// Extrai "agendamento {1..4}" e AGORA também "Token {1..4}"

function parseMaybeJson(v) {
  if (v == null) return null;
  if (typeof v === 'object') return v;
  try { return JSON.parse(String(v)); } catch { return null; }
}

function escapeJsonString(s) {
  // Escapa \ e " para uso seguro dentro de aspas duplas
  return String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

function extractTags(lead) {
  const arr = lead?._embedded?.tags;
  if (!Array.isArray(arr)) {
    return {
      tags_raw: [], tag_ids: [], tag_names: [],
      tag_names_csv: "", tags_string: ""
    };
  }

  const names = arr
    .filter(t => t && (t.name != null || t.id != null))
    .map(t => String(t.name ?? "").trim())
    .filter(name => name.length > 0);

  // dedup por nome (case-insensitive)
  const seen = new Set();
  const dedupNames = names.filter(name => {
    const key = name.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  const tags_raw = dedupNames.map(name => ({ name }));
  const tag_names = dedupNames;
  const tag_ids = arr.map(t => t?.id).filter(v => v != null);

  // Monta a string no formato { "name": "X" },{ "name": "Y" },  (com vírgula final)
  let tags_string = "";
  if (tag_names.length) {
    const parts = tag_names.map(n => `{ "name": "${escapeJsonString(n)}" }`);
    tags_string = parts.join(",") + ","; // vírgula no final
  }

  return {
    tags_raw,
    tag_ids,
    tag_names,
    tag_names_csv: tag_names.join(", "),
    tags_string
  };
}

// --- IDs de campos conhecidos ---
const AGENDAMENTO_FIELD_IDS = {
  agendamento1: 0 /* ID_CAMPO_KOMMO_AGENDAMENTO_1 */,
  agendamento2: 0 /* SEU_ID_AQUI */,
  agendamento3: 0 /* SEU_ID_AQUI */,
  agendamento4: 0 /* SEU_ID_AQUI */,
};

// --- NOVO: IDs de Token ---
const TOKEN_FIELD_IDS = {
  token1: 0 /* SEU_ID_AQUI */,
  token2: 0 /* SEU_ID_AQUI */,
  token3: 0 /* SEU_ID_AQUI */,
  token4: 0 /* SEU_ID_AQUI */,
};

function extractAgendamentos(lead) {
  const cfv = Array.isArray(lead?.custom_fields_values) ? lead.custom_fields_values : [];
  const out = { agendamento1: null, agendamento2: null, agendamento3: null, agendamento4: null };

  // indexa por field_id
  const byId = new Map(cfv.map(f => [Number(f.field_id), f]));

  for (const key of Object.keys(AGENDAMENTO_FIELD_IDS)) {
    const id = AGENDAMENTO_FIELD_IDS[key];
    const f = byId.get(Number(id));
    const val = f?.values?.[0]?.value ?? null;
    out[key] = (val !== undefined && val !== null && String(val).trim() !== "") ? String(val) : null;
  }

  // array em ordem 1..4, apenas com os existentes
  const agendamentos = [out.agendamento1, out.agendamento2, out.agendamento3, out.agendamento4].filter(v => v != null);

  return { ...out, agendamentos };
}

// --- NOVO: extrator de Tokens 1..4 ---
function extractTokens(lead) {
  const cfv = Array.isArray(lead?.custom_fields_values) ? lead.custom_fields_values : [];
  const out = { token1: null, token2: null, token3: null, token4: null };

  const byId = new Map(cfv.map(f => [Number(f.field_id), f]));

  for (const key of Object.keys(TOKEN_FIELD_IDS)) {
    const id = TOKEN_FIELD_IDS[key];
    const f = byId.get(Number(id));
    const val = f?.values?.[0]?.value ?? null;
    out[key] = (val !== undefined && val !== null && String(val).trim() !== "") ? String(val) : null;
  }

  const tokens = [out.token1, out.token2, out.token3, out.token4].filter(v => v != null);

  return { ...out, tokens };
}

const pipelineTarget = $('Edit Fields12').first().json['pipeline - vendas'];

// Converte cada item em objeto
const all = $input.all()
  .map(it => parseMaybeJson(it.json?.data) || it.json)
  .filter(o => o && typeof o === 'object');

// Filtra abertos + não perdidos
let eligible = all.filter(l =>
  l &&
  l.id != null &&
  l.closed_at == null &&
  !l.is_deleted &&
  l.loss_reason_id == null
);

// Prioriza pipeline alvo, se houver
const inTarget = eligible.filter(l => String(l.pipeline_id) === String(pipelineTarget));
if (inTarget.length > 0) eligible = inTarget;

// Ordena pelo updated_at (mais recente primeiro)
eligible.sort((a, b) => (Number(b.updated_at) || 0) - (Number(a.updated_at) || 0));

// Sem elegíveis: retorna item “sentinela”
if (!eligible.length) {
  return [{
    json: {
      found: false,
      id: null,
      name: null,
      pipeline_id: null,
      status_id: null,
      updated_at_unix: null,
      link_self: null,
      tags_raw: [],
      tag_ids: [],
      tag_names: [],
      tag_names_csv: "",
      tags_string: "",
      agendamento1: null,
      agendamento2: null,
      agendamento3: null,
      agendamento4: null,
      agendamentos: [],
      // NOVO: tokens
      token1: null,
      token2: null,
      token3: null,
      token4: null,
      tokens: []
    }
  }];
}

const lead = eligible[0];
const tagsInfo = extractTags(lead);
const agds = extractAgendamentos(lead);
const toks = extractTokens(lead);

return [{
  json: {
    found: true,
    id: lead.id,
    name: lead.name ?? null,
    pipeline_id: lead.pipeline_id ?? null,
    status_id: lead.status_id ?? null,
    updated_at_unix: Number(lead.updated_at) || null,
    link_self: lead._links?.self?.href ?? null,
    // tags
    ...tagsInfo,
    // agendamentos
    ...agds,
    // NOVO: tokens
    ...toks
  }
}];

return $input.all().flatMap(item => {
  let data;
  try {
    data = JSON.parse(item.json.data);
  } catch (err) {
    return [];
  }

  const contacts = data._embedded?.contacts || [];

  return contacts.map(contact => {
    const result = { ...contact };

    // Adiciona lead_id (do primeiro lead)
    result.lead_id = contact._embedded?.leads?.[0]?.id || null;

    // Adiciona link direto para o contato
    result.contact_link = contact._links?.self?.href || null;

    return result;
  });
});

